var HF = N(['SELECT [ALL | DISTINCT | UNIQUE]']),
  xF = N([
    'WITH',
    'FROM',
    'WHERE',
    'GROUP BY',
    'HAVING',
    'PARTITION BY',
    'ORDER [SIBLINGS] BY',
    'OFFSET',
    'FETCH {FIRST | NEXT}',
    'FOR UPDATE [OF]',
    'INSERT [INTO | ALL INTO]',
    'VALUES',
    'SET',
    'MERGE [INTO]',
    'WHEN [NOT] MATCHED [THEN]',
    'UPDATE SET',
    'RETURNING',
  ]),
  Rm = N([
    'CREATE [GLOBAL TEMPORARY | PRIVATE TEMPORARY | SHARDED | DUPLICATED | IMMUTABLE BLOCKCHAIN | BLOCKCHAIN | IMMUTABLE] TABLE',
  ]),
  $s = N([
    'CREATE [OR REPLACE] [NO FORCE | FORCE] [EDITIONING | EDITIONABLE | EDITIONABLE EDITIONING | NONEDITIONABLE] VIEW',
    'CREATE MATERIALIZED VIEW',
    'UPDATE [ONLY]',
    'DELETE FROM [ONLY]',
    'DROP TABLE',
    'ALTER TABLE',
    'ADD',
    'DROP {COLUMN | UNUSED COLUMNS | COLUMNS CONTINUE}',
    'MODIFY',
    'RENAME TO',
    'RENAME COLUMN',
    'TRUNCATE TABLE',
    'SET SCHEMA',
    'BEGIN',
    'CONNECT BY',
    'DECLARE',
    'EXCEPT',
    'EXCEPTION',
    'LOOP',
    'START WITH',
  ]),
  WF = N(['UNION [ALL]', 'MINUS', 'INTERSECT']),
  YF = N([
    'JOIN',
    '{LEFT | RIGHT | FULL} [OUTER] JOIN',
    '{INNER | CROSS} JOIN',
    'NATURAL [INNER] JOIN',
    'NATURAL {LEFT | RIGHT | FULL} [OUTER] JOIN',
    '{CROSS | OUTER} APPLY',
  ]),
  $F = N([
    'ON {UPDATE | DELETE} [SET NULL]',
    'ON COMMIT',
    '{ROWS | RANGE} BETWEEN',
  ]),
  VF = N([]),
  fm = {
    name: 'plsql',
    tokenizerOptions: {
      reservedSelect: HF,
      reservedClauses: [...xF, ...Rm, ...$s],
      reservedSetOperations: WF,
      reservedJoins: YF,
      reservedKeywordPhrases: $F,
      reservedDataTypePhrases: VF,
      supportsXor: !0,
      reservedKeywords: Am,
      reservedDataTypes: Sm,
      reservedFunctionNames: hm,
      stringTypes: [
        { quote: "''-qq", prefixes: ['N'] },
        { quote: "q''", prefixes: ['N'] },
      ],
      identTypes: ['""-qq'],
      identChars: { rest: '$#' },
      variableTypes: [{ regex: '&{1,2}[A-Za-z][A-Za-z0-9_$#]*' }],
      paramTypes: { numbered: [':'], named: [':'] },
      operators: ['**', ':=', '%', '~=', '^=', '>>', '<<', '=>', '@', '||'],
      postProcess: KF,
    },
    formatOptions: {
      alwaysDenseOperators: ['@'],
      onelineClauses: [...Rm, ...$s],
      tabularOnelineClauses: $s,
    },
  };
function KF(e) {
  let t = it;
  return e.map((r) =>
    Ze.SET(r) && Ze.BY(t)
      ? Object.assign(Object.assign({}, r), { type: g.RESERVED_KEYWORD })
      : (qn(r.type) && (t = r), r),
  );
}
